import { Database } from "bun:sqlite";

const db = new Database("jsonl.db");

// Create table if it doesn't exist
db.run("CREATE TABLE IF NOT EXISTS records (data TEXT)");

const insert = db.prepare("INSERT INTO records (data) VALUES (?)");

const stdin = Bun.stdin;
let buffer = "";

for await (const chunk of stdin) {
  buffer += chunk;
  const lines = buffer.split("\n");
  buffer = lines.pop() || "";

  for (const line of lines) {
    if (line.trim()) {
      try {
        // We store the raw line string to preserve original JSON structure 
        // or we can parse and re-stringify. The prompt says assume valid JSON.
        insert.run(line);
      } catch (e) {
        console.error(`Error inserting line: ${e}`);
      }
    }
  }
}

